"""Copy only named synthetic fixture outputs generated by the app self-test."""
import pathlib,json,shutil,subprocess,sys
root=pathlib.Path(__file__).resolve().parent.parent
source=pathlib.Path(sys.argv[1])
if not source.is_absolute():source=root/source
source=source.resolve()
if not source.is_relative_to(root/'fixtures'):raise RuntimeError('Synthetic fixture source must be inside project fixtures')
record=json.loads((source/'ui-result.json').read_text());cli=root/'releases/LM-Experiment-Workbench-win-x64/experiment-cli.exe'
names=['spec.json','models-response.json','load-request.json','load-response.json','chat-request.json','chat-response.json','outcome.json','manifest.json','manifest.sha256']
docs=root/'docs';assets=docs/'assets';assets.mkdir(exist_ok=True)
for name in ['workbench.png','comparison.png']:shutil.copyfile(source/name,assets/name)
shutil.copyfile(source/'tests/test-results.json',docs/'test-results.json')
examples=[];folders=[]
for label in ['baseline','variant']:
 run_id=record[label]
 if len(run_id)!=32 or any(c not in '0123456789abcdef' for c in run_id):raise RuntimeError('Invalid synthetic run id')
 original=source/'demo'/run_id
 if not original.resolve().is_relative_to(source/'demo'):raise RuntimeError('Fixture escape')
 destination=docs/'fixtures'/label;destination.mkdir(parents=True,exist_ok=True)
 if {p.name for p in original.iterdir()}!=set(names):raise RuntimeError('Unexpected synthetic bundle files')
 for name in names:
  p=original/name
  if p.is_symlink() or p.is_junction() or not p.is_file():raise RuntimeError('Invalid fixture input')
  shutil.copyfile(p,destination/name)
 guard=json.loads(subprocess.run([str(cli),'--guard',str(original)],cwd=root,capture_output=True,text=True,check=True).stdout)
 examples.append({'label':label,'spec':json.loads((original/'spec.json').read_text()),'outcome':json.loads((original/'outcome.json').read_text()),'manifest':json.loads((original/'manifest.json').read_text()),'chat':json.loads((original/'chat-response.json').read_text()),'guard':guard})
 folders.append(original)
comparison=json.loads(subprocess.run([str(cli),'--compare',*(str(p) for p in folders)],cwd=root,capture_output=True,text=True,check=True).stdout)
(docs/'examples.json').write_text(json.dumps({'backend':'controlled loopback stub; no inference','runs':examples,'comparison':comparison},indent=2),encoding='utf-8')
print('Synthetic showcase prepared:2bundles,2native renders,production CLI compare/guard results')
